2. **정리 함수 반환**: `useEffect`의 반환값으로 정리 함수를 반환합니다. 이 정리 함수는 컴포넌트가 언마운트되거나 의존성 배열의 값이 변경될 때 호출됩니다.

아래는 비동기 작업을 수행하고 정리하는 예시입니다:

```javascript
import React, { useEffect, useState } from 'react';

const MyComponent = () => {
    const [data, setData] = useState(null);

    useEffect(() => {
        let isMounted = true; // 컴포넌트가 마운트되었는지 추적

        const fetchData = async () => {
            try {
                const response = await fetch('https://api.example.com/data');
                const result = await response.json();
                if (isMounted) { // 컴포넌트가 여전히 마운트된 경우에만 상태 업데이트
                    setData(result);
                }
            } catch (error) {
                console.error('Error fetching data:', error);
            }
        };

        fetchData();

        return () => {
            isMounted = false; // 정리 함수에서 isMounted를 false로 설정
        };
    }, []); // 의존성 배열

    return (
        <div>
            {data ? <pre>{JSON.stringify(data, null, 2)}</pre> : 'Loading...'}
        </div>
    );
};

export default MyComponent;
```

